    trapExamples: [{ question: "846÷3 を計算しましょう。", wrongAnswer: "28", trapExplanation: "8÷3＝2、24÷3＝8まで計算して、6をおろすのをわすれた。まだ一のくらいがのこっている。答えは3けたの282。", correctAnswer: "282", correctExplanation: "8÷3＝2あまり2、24÷3＝8、6÷3＝2。商は 2・8・2 で、282。" }],
