    trapExamples: [{ question: "4.8Lの水を6つに分けます。1つ分は何Lですか。", wrongAnswer: "28.8L", trapExplanation: "かけ算（4.8×6）にしてしまいました。分けるのは、全体÷いくつ分のわり算です。", correctAnswer: "0.8L", correctExplanation: "全体÷いくつ分＝1つ分。4.8÷6＝0.8です。0.8×6＝4.8でたしかめられます。" }],
