    trapExamples: [{ question: "2と3/4を、かぶんすうで書きましょう。", wrongAnswer: "8/4", trapExplanation: "整数×分母だけをして、分子の3をたすのをわすれました。", correctAnswer: "11/4", correctExplanation: "2は1/4が8こ分で、3こ分をたして11こ分です。2×4＋3＝11だから、11/4です。" }],
